/bin/zsh -lc "node <<'NODE'
const fs = require('node:fs');
const assert = require('node:assert/strict');
const html = fs.readFileSync('index.html','utf8');
const src = html.match(/<script>([\\s\\S]*?)<\\/script>/)[1];
const cut = src.indexOf('    function byId(id)');
new Function(src.slice(0,cut) + '\\nglobalThis.Simulation=Simulation; globalThis.Driver=AnimationDriver; globalThis.selfTest=runDeterministicSelfTest;\\n}());')();
const report = {};

// Exact deterministic replay and JSON-safe snapshots.
function actionScript(seed) {
  const s = new Simulation(seed,'healthy');
  s.setTrafficRate(0); s.config.transientFailureRate=0; s.events=[]; s.eventSeq=0;
  s.sendRequest({operation:'write',tenantId:'TENANT-X',key:'acct:x',idempotencyKey:'idem-x',value:'v1',serviceMs:300});
  s.advanceBy(1700);
  s.sendRequest({operation:'read',tenantId:'TENANT-X',key:'acct:x',serviceMs:300});
  s.advanceBy(2300);
  return JSON.stringify(s.snapshot());
}
const replayA=actionScript(98765), replayB=actionScript(98765);
assert.equal(replayA,replayB);
report.determinism={pass:true,bytes:replayA.length};

// Pause driver and manual step.
const clock=new Simulation(1,'healthy'); clock.setTrafficRate(0); clock.playing=false;
const driver=new Driver(clock); driver.frame(1000); driver.frame(5000); assert.equal(clock.time,0); clock.advanceBy(500); assert.equal(clock.time,500);
report.pauseStep={pass:true,pausedTime:0,steppedTime:clock.time};

// Scenario behavior.
report.scenarios={};
for (const name of ['healthy','flash-crowd','database-outage','poison-message','stale-replica']) {
  const s=new Simulation(1337,name);
  const checkpoints=[];
  for (const t of [2000,12000,26000,34000]) { s.advanceBy(t-s.time); checkpoints.push({t,q:s.queue.length,retry:s.retryScheduler.items.length,dlq:s.deadLetters.length,commits:s.primary.commits,rejected:s.gateway.rejected,stale:s.replica.staleReads,circuit:s.circuit.state,primary:s.primary.available,finite:(function finite(v){if(typeof v==='number')return Number.isFinite(v);if("'!v||typeof v!=='"'object')return true;return Object.values(v).every(finite)})(s.snapshot().metrics)}); }
  assert.ok(checkpoints.every(x=>x.finite));
