  this.addPacket("route-retry-queue", request.id, "retry", 700, "↻");
  return true;
};

Simulation.prototype.sampleMetrics = function () {
  var now = this.time;
  var windowStart = now - 5000;
  var recentSuccess = this.successOutcomes.filter(function (item) { return item.time > windowStart; });
  var recentFailures = this.failureOutcomes.filter(function (item) { return item.time > windowStart; });
  var denominatorSeconds = Math.max(1, Math.min(5, now / 1000 || 1));
  var recentLatencies = this.successOutcomes.filter(function (item) { return item.time > now - 20000; }).map(function (item) { return item.latency; });
  this.metrics.throughput = recentSuccess.length / denominatorSeconds;
  this.metrics.p95Latency = percentile95(recentLatencies);
  this.metrics.errorRate = recentFailures.length + recentSuccess.length ? recentFailures.length / (recentFailures.length + recentSuccess.length) : 0;
  this.metrics.queueDepth = this.queue.length;
  this.metrics.queuePeak = Math.max(this.metrics.queuePeak, this.queue.length);
  this.metrics.eventRate = this.events.filter(function (event) { return event.time > windowStart; }).length / denominatorSeconds;

