/bin/zsh -lc "node <<'NODE'
const fs=require('node:fs'),assert=require('node:assert/strict');const h=fs.readFileSync('index.html','utf8'),src=h.match(/<script>([\\s\\S]*?)<\\/script>/)[1],cut=src.indexOf('    function byId(id)');new Function(src);new Function(src.slice(0,cut)+'\\nglobalThis.S=Simulation;globalThis.D=AnimationDriver;globalThis.ST=runDeterministicSelfTest;\\n}());')();
const report={};function finite(v){if(typeof v==='number')return Number.isFinite(v);if("'!v||typeof v!=='"'object')return true;return Object.values(v).every(finite)}
// Determinism, partitioning, pause and zero seed.
function scripted(seed){const x=new S(seed,'healthy');x.setTrafficRate(0);x.config.transientFailureRate=0;x.events=[];x.eventSeq=0;x.sendRequest({operation:'write',key:'det:1',idempotencyKey:'det:1',serviceMs:300});x.advanceBy(2200);x.sendRequest({operation:'read',key:'det:1',serviceMs:300});x.advanceBy(3200);return JSON.stringify(x.snapshot())}
assert.equal(scripted(0),scripted(0));const p1=new S(12,'healthy'),p2=new S(12,'healthy');p1.setTrafficRate(0);p2.setTrafficRate(0);p1.config.transientFailureRate=0;p2.config.transientFailureRate=0;p1.sendRequest({operation:'write',key:'partition',idempotencyKey:'partition',serviceMs:300});p2.sendRequest({operation:'write',key:'partition',idempotencyKey:'partition',serviceMs:300});p1.advanceBy(100);for(let i=0;i<100;i++)p2.advanceBy(1);assert.equal(JSON.stringify(p1.snapshot()),JSON.stringify(p2.snapshot()));const clock=new S(1,'healthy');clock.setTrafficRate(0);clock.playing=false;const drv=new D(clock);drv.frame(0);drv.frame(5000);assert.equal(clock.time,0);clock.advanceBy(500);assert.equal(clock.time,500);report.clock={deterministic:true,partitionIndependent:true,seedZero:new S(0,'healthy').seed,pause:true,step:500};
// Causal travel gate.
const causal=new S(2,'healthy');causal.setTrafficRate(0);causal.config.transientFailureRate=0;const cid=causal.sendRequest({operation:'write',key:'causal',idempotencyKey:'causal',serviceMs:300});assert.equal(causal.requests.get(cid).state,'client_transit');assert.equal(causal.gateway.inbox.length,0);causal.advanceBy(300);assert.equal(causal.gateway.inbox.length,0);causal.advanceBy(100);assert.equal(causal.requests.get(cid).state,'queue_transit');causal.advanceBy(400);assert.equal(causal.requests.get(cid).state,'worker_transit');causal.advanceBy(400);assert.equal(causal.requests.get(cid).state,'processing');causal.advanceBy(300);assert.equal(causal.requests.get(cid).state,'db_transit');assert.equal(causal.primary.commits,0);causal.advanceBy(500);assert.equal(causal.primary.commits,1);report.causalPackets={pass:true,requestId:cid,commitAt:causal.time};
// Scenarios.
report.scenarios={};for(const name of ['healthy','flash-crowd','database-outage','poison-message','stale-replica']){const x=new S(1337,name);const pts=[];for(const t of [2000,12000,26000,40000]){x.advanceBy(t-x.time);pts.push({t,q:x.queue.length,retry:x.retryScheduler.items.length,dlq:x.deadLetters.length,condition:x.currentCondition(),primary:x.primary.available,circuit:x.circuit.state,commits:x.primary.commits,rejected:x.gateway.rejected,stale:x.replica.staleReads,finite:finite(x.snapshot().metrics)});}assert.ok(pts.every(v=>v.finite));if(name==='healthy'){assert.equal(pts[3].circuit,'closed');assert.ok(pts[3].q<6);}if(name==='flash-crowd'){assert.ok(pts[1].q>20&&pts[1].rejected>0);assert.equal(pts[3].q,0);}if(name==='database-outage'){assert.equal(pts[1].commits,0);assert.equal(pts[1].primary,false);assert.equal(pts[3].q,0);assert.equal(pts[3].retry,0);assert.equal(pts[3].circuit,'closed');}if(name==='poison-message'){assert.ok(pts[1].dlq>=1);assert.equal(pts[1].condition,'failed');}if(name==='stale-replica'){assert.ok(pts[1].stale>=1);}report.scenarios[name]=pts;}
// Duplicate, direct outage recovery, lease loss, DLQ replay, stale convergence.
