function renderPackets() {
  var layer = byId("packet-layer");
  var html = [];
  simulation.packets.forEach(function (packet) {
    if (packet.startAt > simulation.time || packet.endAt + 900 < simulation.time) return;
    var path = byId(packet.route);
    if (!path || typeof path.getTotalLength !== "function") return;
    var duration = Math.max(1, packet.endAt - packet.startAt);
    var progress = clamp((simulation.time - packet.startAt) / duration, 0, 1);
    if (reducedMotion.matches && progress > 0 && progress < 1) progress = 0.5;
    var point = path.getPointAtLength(path.getTotalLength() * progress);
    var selectedClass = selection.type === "request" && selection.id === packet.requestId ? " selected-packet" : "";
    html.push("<g class=\"packet " + packet.kind + selectedClass + "\" transform=\"translate(" + point.x.toFixed(2) + " " + point.y.toFixed(2) + ")\" data-request-id=\"" + escapeHtml(packet.requestId || "") + "\" tabindex=\"0\" role=\"button\" aria-label=\"Inspect " + escapeHtml(packet.kind + " packet " + (packet.requestId || "system")) + "\">" + packetShape(packet) + "</g>");
  });
  safelyReplaceHtml(layer, html.join(""));
