    simulation.advanceBy(12000);
    assert(simulation.replayDeadLetter(id, true), "Replay control could not find the dead-letter item.");
    simulation.advanceBy(3000);
    var request = simulation.requests.get(id);
    assert(request.state === "completed" && request.result.outcome === "committed", "Repaired replay did not commit.");
    assert(!simulation.deadLetters.some(function (item) { return item.requestId === id; }), "DLQ item remained after replay.");
    return id + " committed once after repair and left the DLQ.";
  });

  run("Expired cache entry is a miss", function () {
    var simulation = quiet(new Simulation(77, "healthy"));
    simulation.config.cacheTtlMs = 2500;
    simulation.setReplicaLag(0);
    simulation.sendRequest({ operation: "write", key: "cache:ttl", idempotencyKey: "cache-write", value: "fresh", serviceMs: 300 });
    simulation.advanceBy(3000);
    simulation.sendRequest({ operation: "read", key: "cache:ttl", serviceMs: 300 });
    simulation.advanceBy(2500);
    simulation.sendRequest({ operation: "read", key: "cache:ttl", serviceMs: 300 });
    simulation.advanceBy(2200);
    var hitsBeforeExpiry = simulation.cache.hits;
    simulation.advanceBy(3000);
    simulation.sendRequest({ operation: "read", key: "cache:ttl", serviceMs: 300 });
    simulation.advanceBy(2500);
    assert(hitsBeforeExpiry >= 1, "Test did not establish an initial cache hit.");
    assert(simulation.cache.hits === hitsBeforeExpiry, "Expired lookup incremented cache hits.");
    assert(simulation.cache.expired >= 1, "Expired entry was not evicted.");
    return "Hit count stayed at " + hitsBeforeExpiry + "; expired misses recorded: " + simulation.cache.expired + ".";
  });

  run("Replica converges after lag clears", function () {
    var simulation = quiet(new Simulation(88, "healthy"));
    simulation.setReplicaLag(5000);
    simulation.sendRequest({ operation: "write", key: "replica:1", idempotencyKey: "replica-write", value: "v-next", serviceMs: 300 });
    simulation.advanceBy(3000);
    assert(simulation.primary.records.has("replica:1") && !simulation.replica.records.has("replica:1"), "Replica was not behind before lag clear.");
    simulation.setReplicaLag(0);
    simulation.advanceBy(100);
    var primary = simulation.primary.records.get("replica:1");
    var replica = simulation.replica.records.get("replica:1");
    assert(replica && replica.version === primary.version && replica.value === primary.value, "Replica did not converge to primary state.");
    return "Replica converged at record version " + replica.version + ".";
  });

  run("Flash-crowd metrics remain finite", function () {
    var simulation = new Simulation(99, "flash-crowd");
    simulation.advanceBy(18000);
    assert(allNumbersFinite(simulation.snapshot().metrics), "At least one metric became NaN or infinite.");
    return "All metric values stayed finite; peak queue depth was " + simulation.metrics.queuePeak + ".";
  });

  return { passed: tests.every(function (test) { return test.pass; }), tests: tests };
}

function byId(id) {
  return document.getElementById(id);
}

function escapeHtml(value) {
  return String(value == null ? "" : value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function formatTime(milliseconds) {
  milliseconds = Math.max(0, Math.floor(milliseconds));
  var minutes = Math.floor(milliseconds / 60000);
  var seconds = Math.floor(milliseconds % 60000 / 1000);
  var millis = milliseconds % 1000;

