  function verify(name, condition, detail) {
    if (!condition) throw new Error(name + '"': ' + detail);
    checks.push(name + ': PASS — ' + detail);
  }
  var self = runDeterministicSelfTest();
  verify('self-test', self.passed && self.tests.length === 10, self.tests.filter(function(t){return t.pass;}).length + '/10 invariants');

  var sub = new Simulation(2026, 'healthy');
  sub.setTrafficRate(0); sub.config.transientFailureRate = 0;
  sub.advanceBy(50);
  var subId = sub.sendRequest({operation:'write', key:'tick:edge', idempotencyKey:'tick-edge', serviceMs:300});
  sub.advanceBy(400);
  var subPacket = sub.packets.find(function(p){return p.requestId === subId;});
  verify('sub-tick causality', sub.time === 450 && sub.requests.get(subId).state === 'client_transit' && subPacket && subPacket.endAt === 500, 't=450 remains in transit until aligned arrival t=500');
  sub.advanceBy(50);
  verify('aligned arrival', sub.requests.get(subId).state "'!== '"'client_transit', 'state advances exactly when the packet arrives');

  var one = new Simulation(8, 'healthy');
  one.setTrafficRate(0); one.config.transientFailureRate = 0;
  var oneId = one.sendRequest({operation:'write', key:'one', idempotencyKey:'one', serviceMs:300});
  one.advanceBy(1000);
  var activeForOne = one.packets.filter(function(p){return p.requestId === oneId && p.startAt <= one.time && p.endAt > one.time;});
  verify('single causal packet', activeForOne.length <= 1, activeForOne.length + ' active hop for one request');

  var scenarioResults = {};
  ['healthy','flash-crowd','database-outage','poison-message','stale-replica'].forEach(function(name){
    var sim = new Simulation(1337, name);
    sim.advanceBy(name === 'healthy' ? 40000 : name === 'stale-replica' ? 16000 : name === 'poison-message' ? 12000 : 40000);
    scenarioResults[name] = sim.snapshot();
  });
  verify('healthy baseline', scenarioResults.healthy.condition === 'nominal' && scenarioResults.healthy.queue.depth < 5, 'nominal with queue depth ' + scenarioResults.healthy.queue.depth);
  verify('flash-crowd recovery', scenarioResults['flash-crowd'].queue.depth === 0 && scenarioResults['flash-crowd'].gateway.rejected > 0, scenarioResults['flash-crowd'].gateway.rejected + ' throttled, queue drained');
  verify('database-outage recovery', scenarioResults['database-outage'].primary.available && scenarioResults['database-outage'].queue.depth === 0 && scenarioResults['database-outage'].retryScheduler.pending === 0, 'primary online, queue and retries drained');
  verify('poison-message DLQ', scenarioResults['poison-message'].deadLetterQueue.count === 1 && scenarioResults['poison-message'].condition === 'failed', 'one permanent failure is visible');
  verify('stale-replica behavior', scenarioResults['stale-replica'].replica.staleReads > 0, scenarioResults['stale-replica'].replica.staleReads + ' stale reads observed');

  var replay = new Simulation(55, 'poison-message');
  replay.setTrafficRate(0); replay.advanceBy(12000);
  var dlq = replay.deadLetters[0];
  verify('DLQ setup', Boolean(dlq), 'poison item reached DLQ');
  replay.replayDeadLetter(dlq.requestId, true); replay.advanceBy(4000);
  verify('DLQ repair replay', replay.requests.get(dlq.requestId).state === 'completed' && replay.deadLetters.length === 0, 'repaired item committed and left DLQ');

  var seedZero = new Simulation(0, 'healthy');
  verify('seed zero', seedZero.seed === 0, 'integer seed 0 is preserved');
  globalThis.__checks = checks;
}());"'`;
new Function(head + body)();
console.log(globalThis.__checks.join('"'\\n'));
NODE"

